  str_n34_dispatch_task_1_log_1 = "0.5 horas en la investigación\nEntrando en terreno difícil, estamos reduciendo la velocidad.",
  str_n34_dispatch_task_1_log_2 = "1 hora en la investigación\n¡Vaya, el viento está realmente desatado! ¡Pisa los frenos! ¡Ahora!",
  str_n34_dispatch_task_1_log_3 = "1.5 horas en la investigación\nEl vehículo se ha averiado. Montando un campamento temporal para reparaciones. Benny, Kuro y Revy se quedan de guardia.",
  str_n34_dispatch_task_1_log_4 = "3 horas en la investigación\nEl vehículo está en funcionamiento de nuevo y estamos en camino para llegar al Puesto Avanzado 459 pronto.",
