  str_n34_dispatch_task_2_log_1 = "0.5 horas en la investigación\nAcercándonos a la ubicación objetivo, estamos confirmando el lugar exacto.",
  str_n34_dispatch_task_2_log_2 = "1 hora en la investigación\n¡El viento sopla como loco! ¡Sin parar! ¡Parece que nos vamos a perder!",
  str_n34_dispatch_task_2_log_3 = "1.2 horas en la investigación\nParece que nos hemos desviado un poco. No tenemos idea de nuestras direcciones...",
  str_n34_dispatch_task_2_log_4 = "1.22 horas en la investigación\nNo hay que preocuparse. Estamos de vuelta en el camino y buscando la Estación de Suministros 9543.",
  str_n34_dispatch_task_2_log_5 = "4 horas en la investigación\nEstación de suministros 9543 localizada, enterrada profundamente bajo tierra. Estamos limpiando el lugar ahora.",
  str_n34_dispatch_task_2_log_6 = "4.2 horas en la investigación\nNo hay señales de actividad de Eclipsite. Actualmente estamos haciendo inventario de suministros.",
  str_n34_dispatch_task_2_log_7 = "7 horas en la investigación\nHay suficiente combustible; las raciones están organizadas, aunque el agua escasea un poco. Estamos trabajando en un plan de distribución.",
  str_n34_dispatch_task_2_log_8 = "7.5 horas en la investigación\nLa reposición de suministros está hecha. Estamos listos para seguir adelante.",
  str_n34_dispatch_task_3_log_1 = "1 hora en la investigación\nSe encuentra el marcador de ruta S78865. Todo parece estar bien.",
  str_n34_dispatch_task_3_log_2 = "1.5 horas en la investigación\n¡El marcador de ruta S78865 está en el lugar equivocado! ¡Reposicionando! Incluso Gram se equivocó esta vez.",
  str_n34_dispatch_task_3_log_3 = "2 horas en la investigación\nSegún nuestra investigación, parece que la marca del camino S78865 ha sido movida. Deben ser esos terribles Eclipsites.",
  str_n34_dispatch_task_3_log_4 = "2.2 horas en la investigación\nHemos asignado un equipo de guardia y estamos intentando restablecer las coordenadas del marcador de ruta S78865.",
  str_n34_dispatch_task_3_log_5 = "4 horas en la investigación\nLas coordenadas han sido reiniciadas. Hemos arreglado el marcador de ruta S78865 en un lugar oculto y registrado su posición.",
  str_n34_dispatch_task_3_log_6 = "4.5 horas en la investigación\nMontando el campamento; manteniéndonos alerta.",
  str_n34_dispatch_task_3_log_7 = "5 horas en la investigación\nGram dice que tendremos que continuar a pie desde aquí. El vehículo se está enterrando. Tenemos que encontrar una cueva, y rápido.",
  str_n34_dispatch_task_3_log_8 = "7 horas en la investigación\n¿Competir en el desierto? ¡No tenemos rival! ¡Esas mochilas no son ningún problema para nosotros en absoluto!",
  str_n34_dispatch_task_3_log_9 = "7.2 horas en la investigación\nSolo para dejarlo claro, yo soy el que lleva las mochilas. Benny and Curo se enfocan en mantenernos en el camino correcto.",
  str_n34_dispatch_task_3_log_10 = "7.5 horas en la investigación\nSentido de dirección... Asegurémonos de no perdernos, ¿de acuerdo?",
  str_n34_dispatch_task_3_log_11 = "9 horas en la investigación\nEn camino hacia el desfiladero. La situación está bajo control.",
  str_n34_dispatch_task_4_log_1 = "1.5 horas en la investigación\n¡El desfiladero es increíblemente ancho! ¿Cómo diablos cruzamos esto...",
  str_n34_dispatch_task_4_log_2 = "2 horas en la investigación\nDado los fuertes vientos aquí en el páramo, volar sería peligroso. Un puente nos ayudaría mucho.",
  str_n34_dispatch_task_4_log_3 = "2.5 horas en la investigación\nDe hecho, según la información que tengo, hay un puente de piedra cerca. Solo necesitamos localizar una colina hueca con tres aberturas en el medio. El puente debería estar cerca de allí.",
  str_n34_dispatch_task_4_log_4 = "3 horas en la investigación\nUno, dos, tres... ¡tres aberturas! Esto no parece una colina rocosa, es más como un mini castillo.",
  str_n34_dispatch_task_4_log_5 = "3.5 horas en la investigación\nNos tomamos un descanso de 2 horas, preparándonos para cruzar ese puente.",
  str_n34_dispatch_task_4_log_6 = "5.5 horas en la investigación\nEstamos cruzando el puente. No hay barandillas aquí, así que ten cuidado con las ráfagas del desfiladero. El primero es Gram.",
  str_n34_dispatch_task_4_log_7 = "6 horas en la investigación\nGram ha llegado al otro lado de manera segura. Las cuerdas de seguridad están colocadas y aseguradas.",
  str_n34_dispatch_task_4_log_8 = "[6.5 horas en la investigación]\n¡Hemos llegado al otro lado! Y trajimos a Philyshy con nosotros. Resulta que es bastante ligera.",
  str_n34_dispatch_task_4_log_9 = "7 horas en la investigación\nChandra y Revy han llegado con éxito al otro lado con su equipo. Ahora estamos comunicándonos desde el otro lado del desfiladero, y todos tomarán un descanso de 3 horas.",
  str_n34_dispatch_task_4_log_10 = "10 horas en la investigación\nEl viento se está volviendo más frío... Es hora de seguir adelante.",
  str_n34_dispatch_task_5_log_1 = "1 hora en la investigación\nEl páramo termina aquí, y ¿quién hubiera pensado que habría un pantano tan húmedo en un lugar como este?",
  str_n34_dispatch_task_5_log_2 = "1.5 horas en la investigación\n¡No creerás lo extrañas que son las plantas en este pantano! Muchas de ellas tienen espinas y púas, ¡y lo más sorprendente es que muestran signos de movilidad! ¡Algunas incluso exhalan alientos helados!",
  str_n34_dispatch_task_5_log_3 = "2 horas en la investigación\nNadie puede tocar las plantas aquí. Podrían ser venenosas.",
  str_n34_dispatch_task_5_log_4 = "2.2 horas en la investigación\nDespejaré un camino con mi Alter-Blade, principalmente para romper el hielo.",
  str_n34_dispatch_task_5_log_5 = "2.5 horas en la investigación\nEste pantano por el que avanzamos es una verdadera zona de peligro, principalmente debido a todo el hielo frágil. Pisa sin precaución y podrías atravesarlo y quedar atrapado en él. Incluso si logramos sacarte, estarías empapado. En este frío intenso, eso es un camino rápido hacia la hipotermia.",
  str_n34_dispatch_task_5_log_6 = "3 horas en la investigación\nEncontramos un terreno sólido. Vamos a tomar un descanso de 3 horas para hacer una fogata y secar nuestro equipo y zapatos.",
  str_n34_dispatch_task_5_log_7 = "6 horas en la investigación\n¿Puedes creerlo? ¡Ningún Eclipsite nos molesta! ¡Esto se está volviendo demasiado aburrido!",
  str_n34_dispatch_task_5_log_8 = "6.2 horas en la investigación\nDudo que los Eclipsites alguna vez imaginaron que los Aurorians atravesarían este pantano. Nuestros desafíos son únicamente las amenazas naturales inmediatas. Se acabó el campamento, todos: sigamos avanzando.",
  str_n34_dispatch_task_5_log_9 = "8 horas en la investigación\n¡Todo el pantano! ¡Casi me ahoga!",
  str_n34_dispatch_task_5_log_10 = "8.2 horas en la investigación\nRevy acaba de quedarse atrapada en el pantano. Cuando la sacamos, estaba empapada de pies a cabeza. ¡Pero Gram ha decidido seguir adelante! Esperemos que su instinto acierte esta vez.",
  str_n34_dispatch_task_5_log_11 = "9.5 horas en la investigación\n¡Por fin fuera de ese lío! Incluso me hizo empezar a extrañar la Línea Dunefire.",
  str_n34_dispatch_task_6_log_1 = "1 hora en la investigación\n¡Son colinas! ¡Colinas!",
  str_n34_dispatch_task_6_log_2 = "1.2 horas en la investigación\nEl terreno que tenemos por delante es inquietante, con un campo de visión estrecho. Todos, manténganse alerta y cuidado con las emboscadas de Eclipsites.",
  str_n34_dispatch_task_6_log_3 = "2 horas en la investigación\nEstas columnas... están cubiertas de hielo grueso, reflejando la luz como espejos. Es casi transparente... No bajen la guardia, equipo.",
  str_n34_dispatch_task_6_log_4 = "2.2 horas en la investigación\nParece que estamos oficialmente perdidos, incluso yo puedo darme cuenta de eso.",
  str_n34_dispatch_task_6_log_5 = "2.5 horas en la investigación\nTomemos un descanso de 4 horas primero. Tenemos que asegurarnos de nuestras direcciones antes de continuar.",
  str_n34_dispatch_task_6_log_6 = "7 horas en la investigación\n¡La luz está demasiado tenue! No podemos usar el sol o las estrellas para navegar. Entonces, ¿tenemos que recurrir a... maquinaria?",
  str_n34_dispatch_task_6_log_7 = "7.5 horas en la investigación\nImprovisé una brújula improvisada usando un reloj. Salgamos primero de esta ladera helada.",
  str_n34_dispatch_task_6_log_8 = "8 horas en la investigación\nOliendo un poco de... hedor de Eclipsite.",
  str_n34_dispatch_task_6_log_9 = "8.2 horas en la investigación\nTres Eclipsites aparecieron y fueron cortados en seis pedazos por Revy.",
  str_n34_dispatch_task_6_log_10 = "9 horas en la investigación\nFinalmente salimos de ese bosque de hielo. Aunque no es tan peligroso como el pantano, es muy fácil perderse allí...",
  str_n34_dispatch_task_7_log_1 = "0.5 horas en la investigación\n¡Una enorme cadena montañosa bloquea nuestro camino!",
  str_n34_dispatch_task_7_log_2 = "0.8 horas en la investigación\nActualmente buscamos una ruta alrededor de la cordillera.",
  str_n34_dispatch_task_7_log_3 = "2 horas en la investigación\nEncontramos una entrada a una cueva, pero el lugar está lleno de huellas de Eclipsites. Hemos decidido buscar una ruta alternativa primero.",
  str_n34_dispatch_task_7_log_4 = "5 horas en la investigación\nSin suerte encontrando otro camino. Volvemos a la cueva para montar el campamento y explorar.",
  str_n34_dispatch_task_7_log_5 = "[5.5 horas en la investigación]\nHemos montado nuestro campamento. Decidimos enviar a Revy y Philyshy a la cueva primero. Se espera que regresen en 1 hora.",
  str_n34_dispatch_task_7_log_6 = "6 horas en la investigación\n¡Los Eclipsites acaban de atacar nuestro campamento! No fue un enjambre grande, pero algunos lograron escapar.",
  str_n34_dispatch_task_7_log_7 = "[6.5 horas en la investigación]\nRevy y Philyshy no regresaron a tiempo. Decidimos esperar una hora más aquí.",
  str_n34_dispatch_task_7_log_8 = "[7.5 horas en la investigación]\nRevy y Philyshy aún no han regresado. Ahora Chandra tomará el mando y entraré a la cueva para buscar a los dos.",
  str_n34_dispatch_task_7_log_9 = "8 horas en la investigación\nLos Eclipsites levantaron el campamento una vez más. Nos estamos trasladando a un lugar cercano, colocando la bandera como señal.",
  str_n34_dispatch_task_7_log_10 = "9 horas en la investigación\nInformando al Gran Mariscal: si no regresan en 1 hora, Chandra, Benny y Curo volverán.",
  str_n34_dispatch_task_7_log_11 = "10 horas en la investigación\n¡Gracias a Dios! ¡Han vuelto! ¡Es hora de salir de aquí, todos!",
  str_n34_dispatch_task_1_com_1 = "Gran Mariscal, Gram informa. Cambio.",
  str_n34_dispatch_task_1_com_2 = "Gran Mariscal aquí. Cambio.",
  str_n34_dispatch_task_1_com_3 = "Como registran los documentos, el Puesto Avanzado 459 ha sido destruido por los Eclipsites.",
  str_n34_dispatch_task_1_com_4 = "Cuéntame más sobre las trampas que descubriste. Cambio.",
  str_n34_dispatch_task_1_com_5 = "La mayoría son sumideros naturales y rocas sueltas con un nivel promedio de tácticas y camuflaje, lo que indica que son dispositivos primitivos colocados por los Eclipsites. Cambio.",
  str_n34_dispatch_task_1_com_6 = "¿Qué pasa con los vehículos y el personal? Cambio.",
  str_n34_dispatch_task_1_com_7 = "Todo está normal. Sobre.",
  str_n34_dispatch_task_1_com_8 = "¿Y los suministros? Copiado.",
  str_n34_dispatch_task_1_com_9 = "La comida y el agua son abundantes. También tenemos suficiente combustible para asegurar nuestro avance cerca de la zona de la noche eterna, ya que el almacén fue respetado por los Eclipsites. Cambio.",
  str_n34_dispatch_task_1_com_10 = "Tu equipo de campamento será una preparación de emergencia en caso de avería del vehículo. Por favor, asegúrate de que estén en buen estado. Cambio.",
  str_n34_dispatch_task_1_com_11 = "Sí, Gran Mariscal. Cambio.",
  str_n34_dispatch_task_1_com_12 = "Y presta atención a la salud mental de los miembros del equipo en el camino. Copiado.",
  str_n34_dispatch_task_1_com_13 = "Sí, Gran Mariscal!",
  str_n34_dispatch_task_1_com_14 = "¡Estamos bien!",
  str_n34_dispatch_task_1_com_15 = "Dried fish!",
  str_n34_dispatch_task_1_com_16 = "Uno, dos, tres Eclipsitos, cortados en dos, cuatro, seis partes...",
  str_n34_dispatch_task_1_com_17 = "Parece que están a salvo y sanos ahora, Gran Mariscal. Cambio.",
  str_n34_dispatch_task_1_com_18 = "También lo he notado. Mantente alerta. Cambio.",
  str_n34_dispatch_task_2_com_1 = "¿Has recibido este mensaje? Cambio.",
  str_n34_dispatch_task_2_com_2 = "Las señales están claras. Entendido. Cambio.",
  str_n34_dispatch_task_2_com_3 = "Dijiste que te falta un poco de agua. Cuéntame más. Cambio.",
  str_n34_dispatch_task_2_com_4 = "Si lo decimos con precisión, nos falta agua limpia. El tanque de agua en el Puesto Avanzado 9543 fue contaminado por el cieno.",
  str_n34_dispatch_task_2_com_5 = "Si procesamos el líquido en la estación de suministro, nuestra operación se retrasaría. Así que decidimos usar esa parte de la reserva como agua no potable. Cambio.",
  str_n34_dispatch_task_2_com_6 = "¡Lo que significa que solo podríamos usar agua embarrada para lavarnos las caras entonces!",
  str_n34_dispatch_task_2_com_7 = "Puede que escuche un sonido insoportablemente discordante si lo uso para limpiar el arma.",
  str_n34_dispatch_task_2_com_8 = "Parece que tienes problemas con agua sucia. Cambio.",
  str_n34_dispatch_task_2_com_9 = "Son solo problemas menores. Podemos seguir bebiendo el agua si la hervimos y la filtramos.",
  str_n34_dispatch_task_2_com_10 = "¡Sí! ¡Después de todo, estamos en la naturaleza!",
  str_n34_dispatch_task_2_com_11 = "¡Aún es mucho mejor que el agua fría!",
  str_n34_dispatch_task_2_com_12 = "Aunque el sabor a óxido hace que nos duelan los dientes...",
  str_n34_dispatch_task_2_com_13 = "Al menos tu moral está alta ahora. Sobre.",
  str_n34_dispatch_task_2_com_14 = "Sí, Gran Mariscal. Aún no necesitan mi ayuda. Cambio.",
  str_n34_dispatch_task_2_com_15 = "Sigue adelante. Y recuerda estar alerta todo el camino. Cambio.",
  str_n34_dispatch_task_2_com_16 = "Sí. ¡Vamos! Sobre.",
  str_n34_dispatch_task_3_com_1 = "Informando, Gran Mariscal. Nos dirigimos a la garganta. Cambio.",
  str_n34_dispatch_task_3_com_2 = "Ahora continuarás la operación a pie. ¿Cómo está tu condición? Cambio.",
  str_n34_dispatch_task_3_com_3 = "Hemos planeado nuestra carga. Revy puede llevar la comida y el agua para nuestro equipo, y remodelamos su mochila para ese propósito. Cambio.",
  str_n34_dispatch_task_3_com_4 = "Sería una tarea agotadora para un miembro del equipo. Recuerda cambiar regularmente. Cambio.",
  str_n34_dispatch_task_3_com_5 = "Yo, Benny y Kuro reemplazaremos Revy para cargar el peso en 4 horas. Cambio.",
  str_n34_dispatch_task_3_com_6 = "¿Algún problema en su marcha? Cambio.",
  str_n34_dispatch_task_3_com_7 = "Todavía estamos avanzando en la naturaleza, así que es importante determinar las direcciones. Pero Philyshy parece ser muy bueno en eso.",
  str_n34_dispatch_task_3_com_8 = "Es porque soy el Jefe de Inteligencia, ¡miau!",
  str_n34_dispatch_task_3_com_9 = "No esperaba perder contra ella en la marcha aquí...",
  str_n34_dispatch_task_3_com_10 = "Es bueno ver un poco de competencia entre compañeros de equipo. Estás de buen ánimo ahora, por favor manténlo así, Capitán Gram. Cambio.",
  str_n34_dispatch_task_3_com_11 = "No necesitaría ofrecer mi ayuda si siempre pudiéramos estar de buen humor. Cambio.",
  str_n34_dispatch_task_3_com_12 = "Sería la mejor condición, pero tampoco debes relajarte. Si las cosas se salen de control, puedes retirarte para asegurar que no haya bajas. Cambio.",
  str_n34_dispatch_task_3_com_13 = "Yes, Grand Marshal. Over.",
  str_n34_dispatch_task_4_com_1 = "Cuéntame sobre el otro lado. Copiado.",
  str_n34_dispatch_task_4_com_2 = "El viento no es feroz pero sigue soplando. La temperatura disminuyó. Escarcha en el suelo. Cambio.",
  str_n34_dispatch_task_4_com_3 = "Todos mis pelos se erizan... Hace mucho frío.",
  str_n34_dispatch_task_4_com_4 = "Nos hemos puesto nuestro equipo a prueba de frío y nos hemos acostumbrado a llevarlo puesto. Cambio.",
  str_n34_dispatch_task_4_com_5 = "¿Qué pasa con el puente de piedra? ¿Y cómo regresarás desde allí? Cambio.",
  str_n34_dispatch_task_4_com_6 = "El puente de piedra es una roca erosionada naturalmente. La cuerda de seguridad está firmemente fijada. Incluso Revy no resbaló al caminar por aquí. Cambio.",
  str_n34_dispatch_task_4_com_7 = "¡El puente es muy firme! ¡Incluso podría resistir mis balas!",
  str_n34_dispatch_task_4_com_8 = "El camino por la garganta no es tan peligroso, siempre y cuando no intentes ver lo que hay debajo de ti. Al menos eso es lo que pensaba.",
  str_n34_dispatch_task_4_com_9 = "Las personas que pueden concentrarse fácilmente tienen una ventaja en ello. Puedes dejar que Revy sea el primero cuando regreses de allí. Cambio.",
  str_n34_dispatch_task_4_com_10 = "Revy no es ese tipo de persona... ¡Es solo porque no puede pensar en dos cosas a la vez, miau!",
  str_n34_dispatch_task_4_com_11 = "También sería una ventaja si lo vemos desde cierto punto de vista.",
  str_n34_dispatch_task_4_com_12 = "Tu moral está alta. El camino por delante será más difícil, por favor cuida tu salud y suministros. Informa si hay alguna emergencia. Cambio.",
  str_n34_dispatch_task_4_com_13 = "¡Sí!",
  str_n34_dispatch_task_5_com_1 = "Tos... Gram informa, Gran Mariscal. Cambio.",
  str_n34_dispatch_task_5_com_2 = "¿Qué tal tu condición? ¿Puedes persistir? Cambio.",
  str_n34_dispatch_task_5_com_3 = "Llevo años en Illumina, pero esta es la primera vez que veo un terreno tan extraño. ¡Hace frío y está húmedo, pero la capa de hielo aquí es tan delgada! Creo que traeré al personal del Laboratorio de Investigación aquí. Cambio.",
  str_n34_dispatch_task_5_com_4 = "Basado en mi experiencia, debe haber impurezas invisibles en el agua, por lo que no puede congelarse fácilmente.",
  str_n34_dispatch_task_5_com_5 = "El Jefe de Inteligencia tiene razón. No debemos obtener agua del pantano a menos que sea una emergencia. Cambio.",
  str_n34_dispatch_task_5_com_6 = "Pero he tragado un poco. Tal vez me ahogué con el líquido cuando estaba atrapado en el pantano, y ahora me duele el estómago.",
  str_n34_dispatch_task_5_com_7 = "He revisado su condición. Revy solo tomó un poco, y supongo que su malestar no provino del agua, sino del espasmo causado por el frío y la humedad. Podemos presionar en su abdomen para aliviar el dolor.",
  str_n34_dispatch_task_5_com_8 = "¡Hagámoslo! Revy, avanzaremos contigo con todas nuestras fuerzas!",
  str_n34_dispatch_task_5_com_9 = "¡Estoy aquí! ¡Solo apunta hacia mí!",
  str_n34_dispatch_task_5_com_10 = "Hemos montado nuestro campamento y estamos descansando ahora.",
  str_n34_dispatch_task_5_com_11 = "Por fin, pescado seco y agua hervida... Si tan solo hubiera una taza de café...",
  str_n34_dispatch_task_5_com_12 = "¿Qué tal si los invito a todos después de que regresemos? Mi ración es abundante y seguramente tendrán todo el café o pescado seco que deseen.",
  str_n34_dispatch_task_5_com_13 = "¡Está bien!",
  str_n34_dispatch_task_5_com_14 = "No soy especialmente aficionado al café.",
  str_n34_dispatch_task_5_com_15 = "May ¿Pido ahora un surtido de pescado seco?",
  str_n34_dispatch_task_5_com_16 = "Parece que Chandra juega un papel importante, Gram.",
  str_n34_dispatch_task_5_com_17 = "Sí, Gran Mariscal.",
  str_n34_dispatch_task_6_com_1 = "Gran Mariscal aquí. ¿Cuál es su condición? Cambio.",
  str_n34_dispatch_task_6_com_2 = "Gran Mariscal aquí. Por favor, responde si puedes escucharme. Cambio.",
  str_n34_dispatch_task_6_com_3 = "¡Fue tan peligroso! El hielo parecía espejos.",
  str_n34_dispatch_task_6_com_4 = "¿Espejos? ¿A qué te refieres?",
  str_n34_dispatch_task_6_com_5 = "Dañarían nuestro sentido de orientación, lo que hizo que la marcha fuera mucho más difícil de lo habitual. Incluso nuestra visión se volvió poco confiable allí.",
  str_n34_dispatch_task_6_com_6 = "No estoy seguro de lo que estás diciendo, por favor explícalo. Sobre.",
  str_n34_dispatch_task_6_com_7 = "Aquí. Gram informando, Gran Mariscal.",
  str_n34_dispatch_task_6_com_8 = "Hemos pasado por una zona montañosa. La pendiente era suave, pero el terreno era impredecible y lleno de pilares de piedra cubiertos de hielo.",
  str_n34_dispatch_task_6_com_9 = "Por lo tanto, avanzamos en un bosque de pilares de piedra. Nuestra visión estaba bloqueada por ellos, y nuestros sentidos también se veían perturbados por la luz reflejada en el hielo. Nos sentiríamos mareados e incluso perderíamos el rumbo si nos quedáramos allí demasiado tiempo.",
  str_n34_dispatch_task_6_com_10 = "Si nos afectara gravemente, perderíamos la cordura y nos hundiríamos en la locura.",
  str_n34_dispatch_task_6_com_11 = "Suena peligroso, en efecto... Entonces, ¿cómo podrías salir de ellos?",
  str_n34_dispatch_task_6_com_12 = "Gracias al consejo de Benny and Curo. Armamos un dispositivo para guiarnos usando mi reloj, el cable de acero en el arma de Revy y la polea en nuestro equipo de campamento.",
  str_n34_dispatch_task_6_com_13 = "El dispositivo funcionaba como un bastón. Lo usábamos para sondear el terreno frente a nosotros y, una vez que nos alejábamos de la dirección anterior, el dispositivo indicaría el ángulo que giramos.",
  str_n34_dispatch_task_6_com_14 = "Aunque no fue muy preciso, era mejor que nada. En cuanto al deslumbrante hielo, Chandra sugirió que mantuviéramos nuestras cabezas bajas al marchar.",
  str_n34_dispatch_task_6_com_15 = "Pero, ¿qué pasaría si fuéramos atacados por Eclipsites? ¡Ni siquiera tendríamos tiempo para sacar nuestras armas!",
  str_n34_dispatch_task_6_com_16 = "No importa. Todos serán tratados.",
  str_n34_dispatch_task_6_com_17 = "De todos modos, ya hemos salido. Ahora estamos cerca de la frontera hacia la noche eterna. Cambio.",
  str_n34_dispatch_task_6_com_18 = "Mantén un ojo en la condición del equipo y no te esfuerces demasiado. Retírate si es necesario. Cambio.",
  str_n34_dispatch_task_7_com_1 = "Chandra, Chandra! ¿Cuál es tu estado? Cambio.",
  str_n34_dispatch_task_7_com_2 = "Sin bajas. Hemos regresado. Cambio.",
  str_n34_dispatch_task_7_com_3 = "Cuéntame brevemente lo que viste en el camino. Cambio.",
  str_n34_dispatch_task_7_com_4 = "¡Una cueva completamente oscura! ¡Con un techo alto y un espacio enorme!",
  str_n34_dispatch_task_7_com_5 = "Y viento.",
  str_n34_dispatch_task_7_com_6 = "Y esto puede afectar la luz en su interior. Solo podríamos ver a unos pocos pasos de distancia, incluso si encendemos la mejor lámpara.",
  str_n34_dispatch_task_7_com_7 = "El aire fétido dificultaba la respiración y las personas podrían perderse fácilmente allí.",
  str_n34_dispatch_task_7_com_8 = "Te contaré lo que pasó después, Gran Mariscal.",
  str_n34_dispatch_task_7_com_9 = "Recibí su informe. Copiado.",
  str_n34_dispatch_task_7_com_10 = "Esperábamos que regresaran en 1 hora, pero no lo hicieron, incluso si esperamos otra hora. Así que entré en la cueva para buscarlos. Cambio.",
  str_n34_dispatch_task_7_com_11 = "¿Qué suministros tenías? Copiado.",
  str_n34_dispatch_task_7_com_12 = "Comida y agua para 7 días, armas, equipo a prueba de frío, una lámpara para un día entero de iluminación, herramientas de escalada, cuerdas de seguridad y un bidón de combustible. Cambio.",
  str_n34_dispatch_task_7_com_13 = "¿No llevaste el dispositivo de dirección contigo? Cambio.",
  str_n34_dispatch_task_7_com_14 = "Los compañeros de equipo en el campamento lo necesitarían para guiarlos a través de las desagradables columnas de piedra si no pudiera regresar. Cambio.",
  str_n34_dispatch_task_7_com_15 = "Eres un buen capitán. Continúa. Sobre.",
  str_n34_dispatch_task_7_com_16 = "Así como lo hemos hecho antes, mantuve la cabeza baja y me concentré en sus huellas en el suelo. Marqué algunas borrosas con clavijas de escalada, y después de quedarme sin ellas, corté un trozo de mi cuerda y lo sumergí en el combustible para marcar las huellas poco claras. Cambio.",
  str_n34_dispatch_task_7_com_17 = "La gasolina puede atraer a los Eclipsites. Una opción arriesgada, pero has demostrado tener razón. Cambio.",
  str_n34_dispatch_task_7_com_18 = "No podemos depender siempre de nuestra suerte, Gran Mariscal. Actualmente, hemos llegado a lo más lejos en nuestra exploración de la noche eterna. Cambio.",
  str_n34_dispatch_task_7_com_19 = "Regresa ahora. Abandona algunos suministros si es necesario. Cambio.",
  str_n34_dispatch_task_7_com_20 = "Yes, Grand Marshal. Over.",
  str_n34_dispatch_task_7_com_21 = "Ten cuidado y asegura la seguridad del personal primero. Te esperaré en Crepúsculo. Cambio.",
  str_n34_dispatch_task_7_com_22 = "Nos vemos allí, Gran Mariscal. Cambio."
}
return config
